import {shuffle,chapterMatches} from './core.js?v=15';
import {Stopwatch} from './stopwatch.js?v=9';
import {applyClassification,linkedChapters} from './classification.js?v=15';
import {improveMath,renderMath} from './math-format.js?v=9';
import {archivePapers,validateArchive} from './paper-archive.js?v=15';
import {account,mountAccountLink} from './account-client.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const math=renderMath;
let layout={},data,archive,chapters,stage='P1',year='',month='',chapter=[],record='all',query='',page=1,randomIds=null;
let allowCrossChapter=false,order=new Map();
const SIZE=4,opened=new Set();let state={saved:[],done:[]};
try{const v=JSON.parse(localStorage.getItem('pure-past-records-v1'));if(v&&Array.isArray(v.saved)&&Array.isArray(v.done))state=v;}catch{}
let recordBusy=false;
async function save(){if(account.enabled){try{await account.commitState('past',state);}catch(e){state=account.getState('past');render();throw e;}return;}try{localStorage.setItem('pure-past-records-v1',JSON.stringify(state));}catch{alert('本浏览器未允许保存记录。');}}
function options(){
 $('#past-chapter').innerHTML=chapters[stage].map(c=>`<div class="chapter-row"><button class="chapter-pick ${chapter.includes(c.id)?'selected':''}" data-past-chapter="${c.id}" aria-pressed="${chapter.length===1&&chapter[0]===c.id}"><span>${c.id} · ${esc(c.zh)}</span><small>${data.questions.filter(q=>q.stage===stage&&linkedChapters(q).includes(c.id)).length}</small></button><label class="chapter-add"><input type="checkbox" value="${c.id}" ${chapter.includes(c.id)?'checked':''} aria-label="多选第${c.id}章"></label></div>`).join('');
 const papers=archivePapers(archive,{stage,year,month,query});
 const row=p=>`<div class="paper-row"><b>${esc(p.title)}</b><br><button class="text-button" data-doc="${p.pdf}" data-title="${esc(p.title)}">查看整卷试题 ↗</button> <button class="text-button" data-doc="${p.markScheme}" data-title="${esc(p.title)} · 官方评分标准">官方评分标准</button><small>${p.questionPracticeAvailable?'附逐题中文解析':'整卷原件及官方评分标准'}</small></div>`;
 $('#paper-directory-title').textContent=`历年整卷档案 · ${stage} · 当前筛选${papers.length}套`;
 $('#paper-directory').innerHTML=papers.map(row).join('')||'<p>此筛选下没有整卷档案。</p>';
 $('#archive-count').textContent=`2019—2025年6月 · ${archive.papers.length}套整卷 · ${data.questions.length}道逐题练习`;
 const selected=year||month||query;
 $('#archive-filter-note').textContent=selected?'整卷目录按卷别、年份、考季及卷名关键词筛选；下方逐题筛选另含章节和知识点。':'已收录2019年至2025年6月可核对的P1、P2、P3整卷及评分标准。';

}
function pool(){const term=query.trim().toLowerCase();return data.questions.filter(q=>q.stage===stage&&(!year||q.year===+year)&&(!month||q.month===+month)&&chapterMatches(q,chapter,allowCrossChapter)&&(record==='all'||record==='saved'&&state.saved.includes(q.id)||record==='done'&&state.done.includes(q.id)||record==='undone'&&!state.done.includes(q.id))&&(!term||[q.id,q.titleZh,q.paper,q.searchText,...q.topics,...chapters[stage].filter(c=>linkedChapters(q).includes(c.id)).flatMap(c=>[c.zh,c.title,'第'+c.id+'章'])].join(' ').toLowerCase().includes(term))).sort((a,b)=>order.get(a.id)-order.get(b.id));}
function solutionSections(q){if(!q.solutionSections?.length)return `<p>${esc(improveMath(q.solutionZh)).replace(/\n/g,'</p><p>')}</p>`;return q.solutionSections.map(s=>`<section class="past-answer-section"><h4>${esc(s.label)}</h4>${s.approach?`<p class="answer-approach"><b>思路：</b>${esc(improveMath(s.approach))}</p>`:''}<ol class="solution-steps">${s.steps.map(t=>`<li>${esc(improveMath(t))}</li>`).join('')}</ol></section>`).join('');}
// Display crops reference untouched source images. Full original pages remain in the reader.
function questionImages(q,p){return (layout[q.id]||q.pages).map(v=>{
 const label=`${p.title} 原卷第${q.number}题，第${v.page}页；点击查看完整原页`;
 if(v.renderFromPdf)return `<figure><button class="past-image-link" data-doc="${v.pdf}" data-page="${v.page}" data-title="${esc(p.title)} · Q${q.number}" aria-label="${esc(label)}"><canvas class="source-pdf-crop" data-pdf-crop="${encodeURIComponent(JSON.stringify(v))}" aria-label="${esc(label)}"></canvas></button></figure>`;
 if(!v.crop)return `<figure><button class="past-image-link" data-doc="${p.pdf}" data-page="${v.page}" data-title="${esc(p.title)} · Q${q.number}"><img src="${v.image}" width="${v.width}" height="${v.height}" loading="lazy" alt="${esc(label)}"></button></figure>`;
 const [x,y,w,h]=v.crop,ratio=(v.width*w)/(v.height*h);
 return `<figure><button class="past-image-link" data-doc="${p.pdf}" data-page="${v.page}" data-title="${esc(p.title)} · Q${q.number}" aria-label="${esc(label)}"><span class="past-crop" style="aspect-ratio:${ratio}"><img src="${v.image}" loading="lazy" alt="${esc(label)}" style="width:${100/w}%;max-width:none;left:${-100*x/w}%;top:${-100*y/h}%"></span></button></figure>`;
}).join('');}
function officialMarkScheme(q,p){
 const images=(q.markSchemePages||[]).map(v=>{const label=`${p.title} 第${q.number}题官方评分标准，第${v.page}页`;return `<figure><button class="past-image-link" data-doc="${p.markScheme}" data-page="${v.page}" data-title="${esc(p.title)} · Q${q.number} · 官方评分标准" aria-label="${esc(label)}"><canvas class="source-pdf-crop" data-pdf-crop="${encodeURIComponent(JSON.stringify(v))}" aria-label="${esc(label)}"></canvas></button></figure>`;}).join('');
 return `<div class="official-scheme-images">${images}</div>`;
}
let cropPdfjs=null;const cropDocuments=new Map();
async function renderPdfCrop(canvas){
 const v=JSON.parse(decodeURIComponent(canvas.dataset.pdfCrop));
 cropPdfjs??=await import('./assets/pdfjs/pdf.mjs');cropPdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.mjs',import.meta.url).href;
 let promise=cropDocuments.get(v.pdf);if(!promise){promise=cropPdfjs.getDocument({url:v.pdf,isEvalSupported:false}).promise;cropDocuments.set(v.pdf,promise);}
 const pdf=await promise,p=await pdf.getPage(v.page),viewport=p.getViewport({scale:1.55}),[x,y,w,h]=v.crop;
 canvas.width=Math.max(1,Math.round(viewport.width*w));canvas.height=Math.max(1,Math.round(viewport.height*h));
 const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);
 await p.render({canvasContext:context,viewport,transform:[1,0,0,1,-viewport.width*x,-viewport.height*y]}).promise;
 for(const mark of v.highlights||[]){const [mx,my,mw,mh]=mark.box,rx=(mx-x)*viewport.width-4,ry=(my-y)*viewport.height-4,rw=mw*viewport.width+8,rh=mh*viewport.height+8;context.strokeStyle='#e6007e';context.lineWidth=3;context.strokeRect(rx,ry,rw,rh);}
 canvas.dataset.ready='true';
}
function mountPdfCrops(root){if(!root?.querySelectorAll)return;for(const canvas of root.querySelectorAll('canvas[data-pdf-crop]:not([data-ready])')){canvas.dataset.ready='loading';renderPdfCrop(canvas).catch(error=>{canvas.dataset.ready='error';console.error(error);});}}
function card(q){const p=data.papers.find(p=>p.id===q.paper),saved=state.saved.includes(q.id),done=state.done.includes(q.id),official=q.officialMarkScheme&&q.markSchemePages?.length;return `<article class="question-card past-card" data-id="${q.id}"><div class="card-head"><div class="card-meta"><span class="q-number">Question ${q.number}</span><span class="tag">${q.stage} · ${q.year}年${q.month}月${q.variant?` · ${esc(q.variant)}卷`:''}</span></div><div class="card-actions"><button class="small-action" data-save="${q.id}" aria-pressed="${saved}">${saved?'已收藏':'收藏'}</button><button class="small-action" data-done="${q.id}" aria-pressed="${done}">${done?'已做':'未做'}</button></div></div><div class="past-images">${questionImages(q,p)}</div><div class="card-footer"><button class="answer-toggle" data-answer="${q.id}" aria-expanded="${opened.has(q.id)}" aria-controls="solution-${q.id}">${opened.has(q.id)?'收起答案':official?'查看官方答案':'查看解析'}</button><button class="text-button" data-doc="${p.pdf}" data-page="${q.sourcePages[0]}" data-title="${esc(p.title)} · Q${q.number}">查看原题</button><button class="text-button" data-doc="${p.markScheme}" data-title="${esc(p.title)} · 官方评分标准">完整评分标准</button>${q.marks?`<span class="total-marks">Total <strong>${q.marks}</strong> marks</span>`:''}</div><section class="past-solution" id="solution-${q.id}" ${opened.has(q.id)?'':'hidden'}><h3>${official?'官方答案与评分标准':'中文分步解答'}</h3><p class="question-coverage"><b>考查范围：</b>${q.stage} · ${chapters[q.stage].filter(c=>linkedChapters(q).includes(c.id)).map(c=>`第${c.id}章 ${esc(c.zh)}`).join('、')}<br><b>主要考点：</b>${q.topics.map(esc).join('、')}</p><p class="past-source">来源：${esc(p.title)} · WMA1${q.stage.slice(1)}/01 · Question ${q.number}。题面及原图保持原样。</p>${official?officialMarkScheme(q,p):solutionSections(q)}<p class="past-source">${esc(q.verification)}${official?'':'。如需核对官方得分点，请打开本卷评分标准。'}</p></section></article>`;}
function render(){let list=pool();if(randomIds)list=randomIds.map(id=>list.find(q=>q.id===id)).filter(Boolean);const pages=Math.max(1,Math.ceil(list.length/SIZE));page=Math.min(page,pages);$('#past-normal').hidden=!randomIds;
 $('#past-results').innerHTML=`<div class="result-row"><span>${stage} · ${chapter.length===chapters[stage].length?'全部章节':chapter.length?chapter.map(c=>'第'+c+'章').join('、'):'未选择章节'} · ${randomIds?'随机练习':'当前筛选'} <strong>${list.length}</strong> 道题</span><span class="past-stats">本阶段已做 ${data.questions.filter(q=>q.stage===stage&&state.done.includes(q.id)).length} / ${data.questions.filter(q=>q.stage===stage).length}</span></div>${list.length?list.slice((page-1)*SIZE,page*SIZE).map(card).join(''):'<div class="empty"><h2>没有符合条件的真题</h2><p>请调整年份、章节或关键词。</p></div>'}<div class="pagination"><button class="secondary" data-turn="-1" ${page<=1?'disabled':''}>← 上一页</button><span>第 ${page} / ${pages} 页</span><button class="secondary" data-turn="1" ${page>=pages?'disabled':''}>下一页 →</button></div>`;
 math($('#past-results'));mountPdfCrops($('#past-results'));}
function reset(){allowCrossChapter=false;$('#past-cross-chapter').checked=false;year=month=query='';chapter=chapters[stage].map(c=>c.id);record='all';page=1;randomIds=null;$('#past-year').value='';$('#past-month').value='';$('#past-record').value='all';$('#past-search').value='';options();render();}
const watch=new Stopwatch();let timerKey=null,timerTick=null;
function drawTimer(){const el=$('#timer-value');if(!el)return;el.value=watch.format();el.textContent=watch.format();$('#timer-start').disabled=watch.running;$('#timer-start').textContent=watch.milliseconds>0?'继续':'开始';$('#timer-pause').disabled=!watch.running;}
function persistTimer(){if(!timerKey)return;try{sessionStorage.setItem('pure-paper-timer:'+timerKey,JSON.stringify({milliseconds:watch.milliseconds}));}catch{}}
function pauseTimer(){watch.pause();clearInterval(timerTick);timerTick=null;persistTimer();drawTimer();}
function chooseTimer(url){const paper=archive.papers.find(p=>p.pdf===url||p.markScheme===url),external=data.externalPapers.find(p=>p.url===url||p.markScheme===url),key=paper?.id||(external?`external-${external.stage}-${external.year}-${external.month}`:url);if(key===timerKey){drawTimer();return;}pauseTimer();timerKey=key;let ms=0;try{ms=JSON.parse(sessionStorage.getItem('pure-paper-timer:'+key))?.milliseconds||0;}catch{}watch.restore(ms);drawTimer();}
let doc=null,pdfjs=null,pdfPage=1,scale=1,token=0,task=null,serial=0;
async function openDoc(url,title,start=1){account.activity('book','past').catch(()=>{});const n=++token;chooseTimer(url);if(!$('#past-reader').open)$('#past-reader').showModal();$('#reader-title').textContent=title;$('#reader-source').href=url+'#page='+start;$('#reader-message').textContent='正在读取原文件…';$('#reader-canvas').hidden=true;scale=1;
 try{pdfjs??=await import('./assets/pdfjs/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.mjs',import.meta.url).href;const next=await pdfjs.getDocument({url,isEvalSupported:false}).promise;if(n!==token){next.destroy();return;}doc?.destroy();doc=next;pdfPage=Math.max(1,Math.min(start,doc.numPages));$('#reader-total').textContent='/ '+doc.numPages;$('#reader-page').max=doc.numPages;$('#reader-message').textContent='';await draw();}catch(e){$('#reader-message').textContent='内嵌阅读暂未载入，可点击“原文件”用浏览器打开。';console.error(e);}}
async function draw(){if(!doc)return;const n=++serial;if(task){try{task.cancel();await task.promise;}catch{}task=null;}try{const p=await doc.getPage(pdfPage);if(n!==serial)return;const base=p.getViewport({scale:1}),fit=Math.min(Math.max(160,$('#reader-scroll').clientWidth-28),1000)/base.width,css=p.getViewport({scale:fit*scale}),dpr=Math.min(devicePixelRatio||1,2),v=p.getViewport({scale:fit*scale*dpr}),c=$('#reader-canvas');c.width=v.width;c.height=v.height;c.style.width=css.width+'px';c.style.height=css.height+'px';c.hidden=false;task=p.render({canvasContext:c.getContext('2d'),viewport:v});await task.promise;if(n!==serial)return;$('#reader-page').value=pdfPage;$('#reader-prev').disabled=pdfPage===1;$('#reader-next').disabled=pdfPage===doc.numPages;$('#reader-zoom').textContent=scale===1?'适合宽度':Math.round(scale*100)+'%';$('#reader-scroll').scrollTo(0,0);}catch(e){if(e?.name!=='RenderingCancelledException')console.error(e);}}
async function init(){try{await account.requireUser();await mountAccountLink();if(account.enabled)state=account.getState('past');const [r,c,a]=await Promise.all([fetch('data/past-bank.json?v=20'),fetch('data/bank.json?v=15'),fetch('data/paper-archive.json?v=18')]);if(!r.ok||!c.ok||!a.ok)throw Error('题库文件不可用');const layoutResponse=await fetch('data/past-layout.json?v=19');if(layoutResponse.ok)layout=(await layoutResponse.json()).questions;data=applyClassification(await r.json(),await (await fetch('data/classification.json?v=15')).json());archive=validateArchive(await a.json());chapters=(await c.json()).chapters;$('#past-year').innerHTML='<option value="">全部年份</option>'+[...new Set(archive.papers.map(p=>p.year))].sort((x,y)=>y-x).map(y=>`<option>${y}</option>`).join('');order=new Map(shuffle(data.questions.map(q=>q.id)).map((id,i)=>[id,i]));if(data.questions.some(q=>q.year>2025||(q.year===2025&&q.month>6)))throw Error('真题年份校验失败');if(innerWidth<=650)$('#past-filters').open=false;const ids=new Set(data.questions.map(q=>q.id));state.saved=state.saved.filter(x=>ids.has(x));state.done=state.done.filter(x=>ids.has(x));const params=new URLSearchParams(location.search);if(chapters[params.get('stage')])stage=params.get('stage');const requestedYear=params.get('year');if(requestedYear&&archive.papers.some(p=>p.stage===stage&&p.year===+requestedYear))year=requestedYear;query=params.get('q')||'';if(['saved','done','undone'].includes(params.get('record')))record=params.get('record');$('#past-record').value=record;$('#past-stage').value=stage;$('#past-year').value=year;$('#past-search').value=query;chapter=chapters[stage].map(c=>c.id);options();render();
 $('#past-chapter').addEventListener('click',e=>{const b=e.target.closest('[data-past-chapter]');if(!b)return;chapter=[+b.dataset.pastChapter];page=1;randomIds=null;options();render();});
 $('#past-chapter').addEventListener('change',()=>{chapter=[...document.querySelectorAll('#past-chapter input:checked')].map(x=>+x.value);page=1;randomIds=null;options();render();});
 for(const id of ['past-all','past-clear'])$('#'+id).addEventListener('click',()=>{chapter=id==='past-all'?chapters[stage].map(c=>c.id):[];page=1;randomIds=null;options();render();});
 $('#past-stage').addEventListener('change',e=>{stage=e.target.value;reset();});for(const [id,set] of [['past-year',v=>year=v],['past-month',v=>month=v],['past-record',v=>record=v]])$('#'+id).addEventListener('change',e=>{set(e.target.value);page=1;randomIds=null;options();render();});$('#past-search').addEventListener('input',e=>{query=e.target.value;page=1;randomIds=null;options();render();});$('#past-reset').addEventListener('click',reset);$('#past-cross-chapter').addEventListener('change',e=>{allowCrossChapter=e.target.checked;page=1;randomIds=null;options();render();});$('#past-normal').addEventListener('click',()=>{randomIds=null;page=1;render();});$('#past-random').addEventListener('click',()=>{const a=pool().filter(q=>!state.done.includes(q.id));for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}randomIds=a.slice(0,5).map(q=>q.id);page=1;render();});
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.answer){const id=b.dataset.answer;opened.has(id)?opened.delete(id):opened.add(id);const panel=$('#solution-'+id);panel.hidden=!opened.has(id);b.setAttribute('aria-expanded',String(opened.has(id)));b.textContent=opened.has(id)?'收起答案':'查看官方答案';math(panel);if(opened.has(id))account.activity('solution','past',id).catch(()=>{});}for(const [field,key] of [['save','saved'],['done','done']])if(b.dataset[field]){if(recordBusy)return;recordBusy=true;try{const id=b.dataset[field];state[key]=state[key].includes(id)?state[key].filter(x=>x!==id):[...state[key],id];await save();render();}catch(error){alert(error.message);}finally{recordBusy=false;}}if(b.dataset.turn){page+=+b.dataset.turn;render();$('#past-results').scrollIntoView({block:'start'});}if(b.dataset.doc)openDoc(b.dataset.doc,b.dataset.title,+b.dataset.page||1);});
 if(account.enabled){account.addEventListener('records',()=>{state=account.getState('past');render();});account.activity('visit','past').catch(()=>{});}
 $('#timer-start').addEventListener('click',()=>{watch.start();clearInterval(timerTick);timerTick=setInterval(()=>{drawTimer();persistTimer();},250);drawTimer();});$('#timer-pause').addEventListener('click',pauseTimer);$('#timer-reset').addEventListener('click',()=>{pauseTimer();watch.reset();persistTimer();drawTimer();});window.addEventListener('pagehide',pauseTimer);
 $('#reader-close').addEventListener('click',()=>$('#past-reader').close());$('#reader-prev').addEventListener('click',()=>{if(pdfPage>1){pdfPage--;draw();}});$('#reader-next').addEventListener('click',()=>{if(doc&&pdfPage<doc.numPages){pdfPage++;draw();}});$('#reader-page').addEventListener('change',e=>{const n=+e.target.value;if(doc&&Number.isInteger(n)&&n>=1&&n<=doc.numPages){pdfPage=n;draw();}else e.target.value=pdfPage;});$('#reader-plus').addEventListener('click',()=>{scale=Math.min(3,scale+.25);draw();});$('#reader-minus').addEventListener('click',()=>{scale=Math.max(.5,scale-.25);draw();});$('#reader-full').addEventListener('click',async()=>{const el=$('#past-reader'),on=el.classList.toggle('expanded');$('#reader-full').textContent=on?'退出全屏':'全屏阅读';try{if(on&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(!on&&document.fullscreenElement)await document.exitFullscreen();}catch{}draw();});$('#past-reader').addEventListener('close',()=>{pauseTimer();token++;serial++;task?.cancel();$('#past-reader').classList.remove('expanded');$('#reader-full').textContent='全屏阅读';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});});let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if($('#past-reader').open)draw();},150);});}catch(e){console.error(e);$('#past-results').textContent=account.error?.message||'题库未能载入，请刷新页面重试。';}}
init();
